#include "sdk.h"
#define CAP 8192
static char text[CAP],undo[CAP],clipboard[CAP],path[128]="/home/user/Documents/Untitled.txt",status[128];static UiScene scene;
static int window,caret,scroll,path_field,select_all,modified,undo_valid;
static int line_offset(int line){int n=0;while(line>0&&text[n])if(text[n++]=='\n')line--;return n;}
static int line_number(void){int n=0;for(int i=0;i<caret;i++)if(text[i]=='\n')n++;return n;}
static void reveal(void){int line=line_number();if(line<scroll)scroll=line;if(line>=scroll+19)scroll=line-18;}
static void save_undo(void){copy(undo,text);undo_valid=1;}
static void insert(const char *s){u32 size=strlen(text),n=strlen(s);if(select_all){size=0;text[0]=0;caret=0;select_all=0;}if(size+n>=CAP){copy(status,"文稿已达到 8191 字节上限。");return;}for(int i=(int)size;i>=caret;i--)text[i+n]=text[i];memcpy(text+caret,s,n);caret+=(int)n;modified=1;reveal();}
static void save(void){if(Write(path,text,strlen(text))<0||Sync()<0)copy(status,"保存失败，请检查路径与数据磁盘。");else{modified=0;copy(status,"已保存。");Log("NATIVE EDITOR SAVED\n");}}
static void load(void){int n=Read(path,clipboard,CAP-1);if(n<0){copy(status,"读取失败；首版支持最大 8191 字节。");return;}clipboard[n]=0;save_undo();copy(text,clipboard);caret=scroll=modified=select_all=0;copy(status,"已打开文稿。");}
static void draw(void){ui_begin(&scene);ui_button(&scene,18,43,94,"新建");ui_button(&scene,124,43,94,"打开");ui_button(&scene,230,43,94,"保存");ui_button(&scene,336,43,94,"撤销");ui_fill(&scene,18,84,665,28,path_field?0xe4efff:0xf0f2f5);ui_text(&scene,23,88,path);int at=line_offset(scroll);for(int row=0;row<19;row++){int start=at,n=0;char line[94];while(text[at]&&text[at]!='\n'){if(n<92)line[n++]=text[at];at++;}line[n]=0;if(select_all)ui_fill(&scene,18,125+row*20,665,20,0xdce8f8);ui_mono(&scene,23,127+row*20,line,0x24252a);if(caret>=start&&caret<=at)ui_fill(&scene,23+(caret-start)*7,127+row*20,1,16,0x355e9a);if(text[at]=='\n')at++;else break;}ui_text(&scene,18,524,status);ui_text(&scene,520,524,modified?"未保存":"已保存");Scene(window,&scene);}
static void key(UiEvent *e){if(path_field){u32 n=strlen(path);if(e->type==MSG_TEXT){char bytes[4];int count=text_encode((u32)e->key,bytes);if(n+(u32)count<128){memcpy(path+n,bytes,(u32)count);path[n+count]=0;}}else if(e->key==1)path[0]=0;else if(e->key==8&&n)path[text_previous(path,n)]=0;else if(e->key==13)path_field=0;else if(e->key>=32&&e->key<127&&n<127){path[n]=(char)e->key;path[n+1]=0;}return;}
 if(e->type==MSG_TEXT){char bytes[5]={0};text_encode((u32)e->key,bytes);save_undo();insert(bytes);return;}int k=e->key,n=(int)strlen(text);if(k==19){save();return;}if(k==1){select_all=1;return;}if(k==3||k==24){api(SYS_CLIP_SET,(u32)text,(u32)n,0);if(k==24){save_undo();text[0]=0;caret=0;modified=1;select_all=0;}return;}if(k==22){int bytes=api(SYS_CLIP_GET,(u32)clipboard,CAP-1,0);if(bytes>=0){clipboard[bytes]=0;save_undo();insert(clipboard);}return;}if(k==26&&undo_valid){copy(clipboard,text);copy(text,undo);copy(undo,clipboard);if(caret>(int)strlen(text))caret=(int)strlen(text);modified=1;select_all=0;return;}
 if(k==0x14b&&caret){caret=(int)text_previous(text,(u32)caret);select_all=0;}else if(k==0x14d&&caret<n){caret++;while(caret<n&&((u8)text[caret]&0xc0)==0x80)caret++;select_all=0;}else if(k==0x148||k==0x150){int line=line_number(),column=caret-line_offset(line),target=line+(k==0x148?-1:1);if(target>=0){caret=line_offset(target);while(column--&&text[caret]&&text[caret]!='\n')caret++;}while(caret&&((u8)text[caret]&0xc0)==0x80)caret--;select_all=0;}else if(k==0x147)caret=line_offset(line_number());else if(k==0x14f){while(text[caret]&&text[caret]!='\n')caret++;}else if(k==8||k==0x153){save_undo();if(select_all){text[0]=0;caret=0;select_all=0;modified=1;}else if(k==8&&caret){int start=(int)text_previous(text,(u32)caret);for(int i=caret;i<=n;i++)text[start+i-caret]=text[i];caret=start;modified=1;}else if(k==0x153&&caret<n){int end=caret+1;while(end<n&&((u8)text[end]&0xc0)==0x80)end++;for(int i=end;i<=n;i++)text[caret+i-end]=text[i];modified=1;}}else if(k==13||k==9||(k>=32&&k<127)){char bytes[2]={(char)(k==13?'\n':k),0};save_undo();insert(k==9?"  ":bytes);}reveal();}
int main(void){if(Arguments()[0]&&strlen(Arguments())<128){copy(path,Arguments());load();}window=Window("原生文本编辑器 / Ring 3",705,565);if(window<0)return 1;api(SYS_WINDOW_POLICY,(u32)window,1,0);draw();for(;;){UiEvent e;if(Event(&e)!=0){Yield(1);continue;}if(e.type==MSG_CLOSE){char answer[128];if(!modified||ui_dialog(window,&scene,"放弃未保存的修改并关闭？",answer,0))return 0;draw();continue;}if(e.type==MSG_KEY||e.type==MSG_TEXT)key(&e);if(e.type==MSG_CLICK){if(e.y>=84&&e.y<112)path_field=1;else if(e.y>=43&&e.y<69){path_field=0;if(e.x>=18&&e.x<112){char answer[128];if(modified&&!ui_dialog(window,&scene,"新建前放弃未保存的修改？",answer,0)){draw();continue;}save_undo();text[0]=0;caret=scroll=0;modified=1;}else if(e.x<218){char answer[128];if(!modified||ui_dialog(window,&scene,"打开前放弃未保存的修改？",answer,0))load();}else if(e.x<324)save();else if(e.x<430&&undo_valid){UiEvent k={MSG_KEY,0,0,0,26};key(&k);}}else if(e.y>=125&&e.y<505){path_field=select_all=0;int line=scroll+(e.y-125)/20,column=(e.x-23)/7;caret=line_offset(line);while(column--&&text[caret]&&text[caret]!='\n')caret++;while(caret&&((u8)text[caret]&0xc0)==0x80)caret--;}}draw();}return 0;}
